it('runs update hooks even when the output VDOM is cached', async () => {
  let renewParent = () => {};
  let effects = 0, commits = 0;
  const Cached = mount(() => {
    updateCallback(() => { effects++; return () => { commits++; }; });
    const output = h('button', {}, 'cached');
    return () => output;
  });
  const Parent = mount(renew => { renewParent=renew; return () => h(Cached, {}); });
  const container = document.createElement('div');
  const destroy = render(h(Parent,{}), container);
  const button = container.firstChild;
  for(let i=1;i<=3;i++) {
    renewParent(); await nextTick();
    expect(effects).toBe(i);
    expect(commits).toBe(i);
    expect(container.firstChild).toBe(button);
  }
  destroy();
});

it('keeps all unmount callbacks before listener removal, then detaches listeners', async () => {
  const log: string[] = [];
  let button: HTMLButtonElement;
  const Child = mount(() => {
    mountCallback(() => () => { log.push('child'); button.click(); });
    return () => h('button', {onClick: () => log.push('click')}, 'child');
  });
  const Parent = mount(() => {
    mountCallback(() => () => { log.push('parent'); button.click(); });
    return () => h('div', {}, h(Child,{}));
  });
  const container=document.createElement('div');
  const destroy=render(h(Parent,{}),container);
  button=container.querySelector('button')!;
  destroy(); await nextTick();
  expect(log).toEqual(['parent','click','child','click']);
  button.click();
  expect(log).toEqual(['parent','click','child','click']);
  expect(container.childNodes.length).toBe(0);
});

